<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { t } from '@/i18n'
import NetworkTopology from '@/components/network/NetworkTopology.vue'
import NetworkAlerts from '@/components/network/NetworkAlerts.vue'
import NetworkRelations from '@/components/network/NetworkRelations.vue'
import NetworkEngineering from '@/components/network/NetworkEngineering.vue'
import { useNetworkStore } from '@/stores/network'
import { hasPosition, nodeState } from '@/network/model'
import { TopologyProjector } from '@/network/topology'
import { ageText, eventLabel, linkEvidenceLabel, reportedLinkLabel, roleLabel, stateLabel, tagLabel, timeText } from '@/network/presentation'
import type { ConnectionMode, LayoutMode, MockScenario, NetworkProtocol, NodeTag, Workspace } from '@/network/types'

const props = withDefaults(defineProps<{ workspace?: Workspace }>(), { workspace: 'real' })
const network = useNetworkStore()
const draftBase = ref('')
const draftProtocol = ref<NetworkProtocol>('network-v1')
watch(() => network.profile, profile => { draftBase.value = profile.apiBaseUrl; draftProtocol.value = profile.protocol }, { immediate: true })
const connectionLabel = computed(() => network.configuration.mode === 'server' ? t('服务器') : t('本地网关'))
const endpointLabel = computed(() => new URL(network.profile.apiBaseUrl || '/', location.origin).href.replace(/\/+$/, ''))
function connect() { void network.connect(network.configuration.mode, { apiBaseUrl: draftBase.value, protocol: draftProtocol.value }) }
function changeMode(value: ConnectionMode) { network.selectConnectionMode(value) }
const search = ref('')
const filter = ref('all')
const linkFilter = ref('all')
const topologyProjector = new TopologyProjector()
const topologyFrame = computed(() => network.snapshot ? topologyProjector.project(network.snapshot, network.now, `${network.connectionKey}:${network.mode}:${network.replay?.id ?? ''}`, network.interrupted) : undefined)
const layout = ref<LayoutMode>('clear')
const selected = ref('')
const selectedLink = ref('')
const replayId = ref('')
try { const v = localStorage.getItem(`network.layout.mode.v2:${props.workspace}`); if (v === 'clear' || v === 'manual' || v === 'gps') layout.value = v } catch { /* optional */ }
watch(layout, v => { try { localStorage.setItem(`network.layout.mode.v2:${props.workspace}`, v) } catch { /* optional */ } })
watch(() => network.snapshot, s => {
  if (!s) return
  if (!s.nodes.some(n => n.id === selected.value)) selected.value = s.nodes.find(n => n.role !== 'gateway')?.id ?? s.nodes[0]?.id ?? ''
  if (!s.links.some(e => e.id === selectedLink.value)) selectedLink.value = ''
})
onMounted(() => void network.start(props.workspace))
onBeforeUnmount(() => network.stop())
const nodes = computed(() => network.displaySnapshot?.nodes.filter(n => {
  const matches = `${n.label} ${n.id} ${tagLabel(n.tag ?? 'node')} ${n.binding?.id ?? ''}`.toLowerCase().includes(search.value.toLowerCase().trim())
  return matches && (filter.value === 'all' || nodeState(n, network.snapshot!, network.now, network.interrupted) === filter.value)
}) ?? [])
const node = computed(() => network.displaySnapshot?.nodes.find(n => n.id === selected.value))
const edge = computed(() => network.snapshot?.links.find(e => e.id === selectedLink.value))
const nodeLinks = computed(() => network.snapshot?.links.filter(e => e.from === selected.value || e.to === selected.value) ?? [])
const maxAge = computed(() => {
  const ages = network.snapshot?.nodes.filter(n => n.role !== 'gateway' && n.reportedAt !== null).map(n => Math.max(0, network.now - n.reportedAt!)) ?? []
  return ages.length ? Math.max(...ages) : null
})
const gpsCount = computed(() => network.snapshot?.nodes.filter(n => (n.role !== 'gateway' || linkFilter.value !== 'wifi') && hasPosition(n, network.now, network.snapshot!.reportTimeoutMs)).length ?? 0)
const healthyLabel = computed(() => network.mode === 'replay' ? t('历史回放') : network.status === 'disabled' ? t('未配置数据服务') : network.status === 'connecting' ? t('正在连接') : network.interrupted ? t('数据服务连接中断') : network.paused ? t('观测已暂停') : network.snapshot?.receiver.state === 'unavailable' ? t('接收器观测中断') : network.snapshot?.receiver.state === 'waiting' ? t('接收器在线，等待节点') : t('观测服务已连接'))
const scenarios = computed<{ value: MockScenario; label: string }[]>(() => [
  { value: 'nominal', label: t('5 节点协同') }, { value: 'dense', label: t('30 节点组网') },
  { value: 'empty', label: t('零节点') }, { value: 'interrupted', label: t('接收中断') },
  { value: 'stale', label: t('报告过期') }, { value: 'no-gps', label: t('无 GPS') },
])
const errorHint = computed(() => network.error === 'NETWORK_SYNTHETIC_REJECTED' ? t('已阻止模拟数据进入真实工作区，请检查服务地址。') : network.error === 'NETWORK_REAL_DATA_IN_MOCK' ? t('演示入口已拒绝实测或未知数据，请使用真实工作区。') : network.error === 'NETWORK_PROVENANCE_UNVERIFIED' ? t('服务没有声明实测性质，已拒绝显示。') : network.error === 'NETWORK_REPLAY_PROVENANCE_MISMATCH' ? t('记录列表混入不同性质的数据，已拒绝载入。') : t('保留最后快照并标为历史，不会自动切换到模拟数据。'))
const labelOf = (id: string) => network.snapshot?.nodes.find(n => n.id === id)?.label ?? id
function choose(id: string) { selected.value = id; selectedLink.value = '' }
function chooseLink(id: string) { selectedLink.value = id; const e = network.snapshot?.links.find(x => x.id === id); if (e && e.from !== selected.value && e.to !== selected.value) selected.value = e.to }
const sourceChange = (event: Event) => void network.selectSource((event.target as HTMLSelectElement).value)
const scenarioChange = (event: Event) => void network.setScenario((event.target as HTMLSelectElement).value as MockScenario)
</script>

<template>
  <div class="network-workspace" data-test="network-workspace">
    <header class="workspace-heading">
      <div><div class="kicker"><span class="signal-bars">▂▄▆</span> NETWORK OPERATIONS</div><h1>{{ t('网络观测工作台') }}<span class="version">{{ workspace === 'mock' ? 'MOCK / 02' : 'STUDIO / 02' }}</span></h1><p>{{ t('看见节点、连接与变化，让每一条链路都有据可查。') }}</p></div>
      <div class="workspace-status"><span class="connection-state" :class="{ warning: network.interrupted || network.status === 'error' || network.snapshot?.receiver.state === 'unavailable', neutral: network.status === 'disabled' || network.status === 'connecting' || network.paused || network.mode === 'replay' }"><i />{{ healthyLabel }}</span><span v-if="network.snapshot" class="num observation-clock">{{ timeText(network.snapshot.observedAt) }} UTC{{ new Date().getTimezoneOffset() <= 0 ? '+' : '−' }}{{ Math.abs(new Date().getTimezoneOffset() / 60) }}</span></div>
    </header>

    <div v-if="workspace === 'mock'" class="simulation-banner" role="status" data-test="network-synthetic"><span class="simulation-badge">MOCK · {{ t('模拟数据') }}</span><span>{{ t('独立模拟演示 · 所有 NODE、GPS 与射频均为合成数据，不接收实机数据。') }}</span><span class="simulation-end">SYNTHETIC ONLY</span></div>
    <section v-else class="connection-panel" data-test="real-connection">
      <div class="source-identity"><strong>{{ t('真实数据工作区') }}</strong><span class="source-kind">{{ connectionLabel }}</span><code>{{ endpointLabel }}</code><span class="provenance-chip" :class="{ unverified: network.snapshot?.provenance === 'unknown' }">{{ network.snapshot ? network.snapshot.provenance === 'measured' ? t('服务声明：实测') : t('旧协议：数据性质未声明') : t('未连接，不显示模拟数据') }}</span></div>
      <form class="connection-form" @submit.prevent="connect">
        <div class="connection-modes" :aria-label="t('数据接入方式')"><button type="button" :aria-pressed="network.configuration.mode === 'server'" @click="changeMode('server')">{{ t('服务器') }}</button><button type="button" :aria-pressed="network.configuration.mode === 'gateway'" @click="changeMode('gateway')">{{ t('本地网关') }}</button></div>
        <label class="endpoint-input"><span>{{ t('数据服务地址') }}</span><input v-model="draftBase" type="text" :aria-label="t('数据服务地址')" :placeholder="network.configuration.mode === 'server' ? 'https://server.example / ' + t('留空使用同源服务') : 'http://127.0.0.1:8794'" autocomplete="off" spellcheck="false"></label>
        <select v-if="network.configuration.mode === 'gateway'" v-model="draftProtocol" :aria-label="t('网关协议')"><option value="lora-v1">LoRa topology v1</option><option value="network-v1">Network snapshot v1</option></select>
        <button type="submit" class="connect-button">{{ t('保存并连接') }}</button><button type="button" class="disconnect-button" :disabled="network.status === 'disabled'" @click="network.disconnect">{{ t('断开') }}</button>
      </form>
      <p class="connection-note">{{ network.configuration.mode === 'gateway' ? t('设备只读，不下发控制。工程接口仅允许接收源选择与本机 SQLite 录制；旧协议性质持续标为未声明。') : t('服务器须提供 Network v1 接口；此工作区拒绝模拟数据，失败不回退。') }}</p>
    </section>
    <div v-if="workspace === 'real' && network.snapshot?.provenance === 'unknown'" class="simulation-banner" role="status" data-test="unverified-gateway">{{ t('旧网关协议没有数据性质声明：当前仅为网关观测，不能标成已验证实测。') }}</div>

    <section class="network-toolbar" :aria-label="t('观测工具')">
      <div v-if="network.capabilities?.engineering" class="segmented" :aria-label="t('邻居取证层')"><button :class="{ active: network.observationLayer === 'lora' }" :aria-pressed="network.observationLayer === 'lora'" :disabled="network.mode !== 'live' || network.busy" @click="network.selectObservationLayer('lora')">{{ t('LoRa 报告') }}</button><button :class="{ active: network.observationLayer === 'wifi' }" :aria-pressed="network.observationLayer === 'wifi'" :disabled="network.mode !== 'live' || network.busy" @click="network.selectObservationLayer('wifi')">{{ t('Wi-Fi 即时 / IP') }}</button></div>
      <div v-if="network.capabilities?.sources.length && network.observationLayer === 'lora'" class="toolbar-group"><span class="toolbar-label">{{ t('接收来源') }}</span><select :aria-label="t('接收来源')" :value="network.capabilities?.selectedSourceId ?? ''" :disabled="!network.capabilities?.sourceSelection || network.busy || network.mode === 'replay'" @change="sourceChange"><option v-if="!network.capabilities" value="">—</option><option v-for="source in network.capabilities?.sources" :key="source.id" :value="source.id" :disabled="source.selectable === false">{{ source.label }}</option></select></div>
      <span class="toolbar-divider" />
      <label class="uplink-toggle"><input type="checkbox" :checked="linkFilter !== 'wifi'" @change="linkFilter = ($event.target as HTMLInputElement).checked ? 'all' : 'wifi'"> {{ t('显示网关上行') }}</label>
      <div class="segmented" :aria-label="t('布局方式')"><button :class="{ active: layout === 'gps' }" :aria-pressed="layout === 'gps'" @click="layout = 'gps'">⌖ {{ t('GPS 布局') }}</button><button :class="{ active: layout === 'clear' }" :aria-pressed="layout === 'clear'" @click="layout = 'clear'">{{ t('清晰布局') }}</button><button :class="{ active: layout === 'manual' }" :aria-pressed="layout === 'manual'" @click="layout = 'manual'">{{ t('手动布局') }}</button></div>
      <div v-if="network.capabilities?.mock" class="scenario-control"><label for="network-scenario">{{ t('模拟场景') }}</label><select id="network-scenario" :value="network.capabilities.scenario" :disabled="network.busy || network.mode === 'replay'" @change="scenarioChange"><option v-for="scenario in scenarios" :key="scenario.value" :value="scenario.value">{{ scenario.label }}</option></select></div>
      <button v-if="network.mode === 'live'" class="observer-button" :disabled="network.status === 'disabled' || network.status === 'connecting' || network.busy" @click="network.togglePause">{{ network.paused ? t('继续观测') : t('暂停观测') }}</button><button v-else class="observer-button primary" @click="network.goLive">{{ t('返回实时') }}</button>
    </section>

    <div v-if="layout === 'gps'" class="gps-summary" data-test="gps-summary"><strong>⌖ {{ t('GPS 布局') }}</strong><span>{{ t('按有效经纬度等比例排列 · 未定位或定位过期的成员仅保留在列表') }}</span><span class="num">{{ gpsCount }} / {{ network.snapshot?.nodes.filter(n => n.role !== 'gateway' || linkFilter !== 'wifi').length ?? 0 }} GPS</span></div>
    <div v-if="network.status === 'disabled'" class="network-message" role="status"><strong>{{ workspace === 'mock' ? t('独立模拟服务尚未启用') : t('网络数据服务尚未启用') }}</strong><p>{{ workspace === 'mock' ? t('请使用独立演示启动器；真实工作区不会启动或回退到模拟数据。') : t('先选择服务器或本地网关，检查地址后连接。此页面不会载入演示数据。') }}</p></div>
    <div v-if="network.error" class="network-error" role="alert"><div><strong>{{ t('无法更新网络观测') }}</strong><span>{{ errorHint }}</span><code>{{ network.error }}</code></div><button v-if="network.mode === 'live'" @click="network.retry">{{ t('重试读取') }}</button></div>

    <section class="metrics" :aria-label="t('网络概览')">
      <div class="metric"><div class="metric-label"><span>{{ t('近期报告节点') }}</span><span class="metric-icon">◉</span></div><strong class="num">{{ network.recent }}<small>/ {{ network.snapshot?.nodes.filter(n => n.role !== 'gateway').length ?? 0 }}</small></strong><span class="metric-hint">{{ t('不含接收网关 · 依报告年龄判断') }}</span></div>
      <div class="metric"><div class="metric-label"><span>{{ t('采样方向') }}</span><span class="metric-icon">⇄</span></div><strong class="num">{{ network.snapshot?.links.filter(e => e.kind === 'wifi').length ?? 0 }}<small>ESP-NOW</small></strong><span class="metric-hint">{{ t('发送方 → 报告者，不推断完整路径') }}</span></div>
      <div class="metric"><div class="metric-label"><span>{{ t('最久报告年龄') }}</span><span class="metric-icon">◷</span></div><strong class="num">{{ ageText(maxAge) }}</strong><span class="metric-hint">{{ t('超过有效期即标为过期') }}</span></div>
      <div class="metric"><div class="metric-label"><span>{{ t('有效定位') }}</span><span class="metric-icon">⌖</span></div><strong class="num">{{ gpsCount }}<small>GPS</small></strong><span class="metric-hint">{{ t('缺失或过期的位置不投到地图') }}</span></div>
    </section>

    <NetworkAlerts v-if="network.snapshot" :snapshot="network.snapshot" :now="network.now" :interrupted="network.interrupted" :paused="network.paused" :replay="network.mode === 'replay'" @select="choose" />

    <div class="observation-grid">
      <aside class="node-panel">
        <div class="panel-title"><h2>{{ t('网络成员') }}</h2><span class="count num">{{ nodes.length }}</span></div>
        <div class="node-filters"><input v-model="search" type="search" :placeholder="t('搜索 NODE、标签或 MAC')" :aria-label="t('搜索网络成员')"><select v-model="filter" :aria-label="t('节点状态筛选')"><option value="all">{{ t('全部观测状态') }}</option><option value="recent">{{ t('近期报告') }}</option><option value="stale">{{ t('报告超时') }}</option><option value="unknown">{{ t('从未观测') }}</option><option value="interrupted">{{ t('观测中断') }}</option></select></div>
        <div class="node-list"><button v-for="n in nodes" :key="n.id" class="node-row" :class="{ selected: selected === n.id }" :aria-pressed="selected === n.id" :data-list-node="n.id" @click="choose(n.id)"><span class="role-icon" :class="[n.role, n.tag]">{{ n.role === 'gateway' ? '▥' : n.tag === 'drone' ? '✣' : n.tag === 'robot' ? '▱' : '◇' }}</span><span class="node-identity"><strong>{{ n.label }} <em v-if="n.role !== 'gateway' && n.tag !== 'node'" class="node-tag">{{ tagLabel(n.tag ?? 'node') }}</em></strong><small class="num">{{ n.id }}</small><span class="node-state" :class="network.snapshot && nodeState(n, network.snapshot, network.now, network.interrupted)"><i />{{ network.snapshot ? stateLabel(nodeState(n, network.snapshot, network.now, network.interrupted)) : '—' }}</span></span><span class="row-chevron">›</span></button><p v-if="!nodes.length" class="list-empty">{{ search ? t('没有匹配的节点') : t('暂无节点报告') }}</p></div>
        <div class="node-footnote">{{ t('未定位成员仍保留在列表中。') }}</div>
      </aside>

      <NetworkTopology v-if="network.displaySnapshot" :snapshot="network.displaySnapshot" :namespace="network.connectionKey" :demo="workspace === 'mock'" :now="network.now" :interrupted="network.interrupted" :selected="selected" :selected-link="selectedLink" :layout="layout" :link-filter="linkFilter" :frame="topologyFrame" @select="choose" @link="chooseLink" />
      <section v-else class="topology-placeholder"><div class="placeholder-symbol">⌁</div><strong>{{ network.status === 'disabled' ? t('等待配置数据服务') : t('正在读取网络快照') }}</strong><span>{{ t('没有有效报告前，不预填节点或链路。') }}</span></section>

      <aside class="inspector">
        <div class="panel-title"><h2>{{ edge ? t('方向详情') : t('节点详情') }}</h2><span class="detail-dot" /></div>
        <template v-if="edge && network.snapshot"><div class="inspector-identity"><span class="detail-overline">LINK INSPECTOR</span><h3>{{ labelOf(edge.from) }} <span>→</span> {{ labelOf(edge.to) }}</h3><span class="type-chip">{{ edge.kind === 'lora' ? t('LoRa 上行') : t('Wi-Fi / ESP-NOW 采样') }}</span></div><dl class="detail-list"><div><dt>{{ t('来源性质') }}</dt><dd>{{ network.snapshot.provenance === 'synthetic' ? t('合成样本') : t('观测样本') }}</dd></div><div><dt>{{ t('采样状态') }}</dt><dd class="link-evidence-state" data-test="link-evidence-state">{{ linkEvidenceLabel(edge, network.snapshot, network.now, network.interrupted) }}</dd></div><div><dt>{{ t('上报关系') }}</dt><dd>{{ reportedLinkLabel(edge) }}</dd></div><div><dt>{{ t('链路有效期') }}</dt><dd data-test="link-validity">{{ edge.validForMs === null ? t('未提供') : ageText(edge.validForMs) }}</dd></div><div><dt>RSSI</dt><dd class="num">{{ edge.rssiDbm ?? '—' }}<small v-if="edge.rssiDbm !== null"> dBm</small></dd></div><div><dt>SNR</dt><dd class="num">{{ edge.snrDb ?? '—' }}<small v-if="edge.snrDb !== null"> dB</small></dd></div><div><dt>{{ t('信道') }}</dt><dd class="num">{{ edge.channel ?? '—' }}</dd></div><div><dt>{{ t('样本年龄') }}</dt><dd class="num">{{ ageText(edge.sampledAt === null ? null : network.now - edge.sampledAt) }}</dd></div></dl><p class="evidence-note">{{ edge.kind === 'lora' ? t('此方向是节点到网关的 LoRa 接收，不能当作板间 Wi-Fi 信号质量。') : t('此方向来自采样报告，不证明现在仍可通信，也不代表端到端交付。') }}</p><p v-if="edge.validForMs === null" class="evidence-note" data-test="unknown-validity-note">{{ t('源未提供链路有效期；近期不等于仍然有效，未知也不等于已经过期。') }}</p><button class="back-to-node" @click="selectedLink = ''">{{ t('返回节点详情') }}</button></template>
        <template v-else-if="node && network.snapshot"><div class="inspector-identity"><span class="detail-overline">NODE INSPECTOR</span><h3>{{ node.label }}</h3><span class="type-chip">{{ node.role === 'gateway' ? roleLabel(node.role) : tagLabel(node.tag ?? 'node') }}</span><code>{{ node.id }}</code></div><div v-if="node.role !== 'gateway'" class="tag-editor"><label for="network-node-tag">{{ t('NODE 类型标签') }}</label><select id="network-node-tag" :value="node.tag ?? 'node'" @change="network.setTag(node.id, ($event.target as HTMLSelectElement).value as NodeTag)"><option value="node">NODE</option><option value="drone">{{ t('标签：无人机') }}</option><option value="robot">{{ t('标签：机器人') }}</option></select><small>{{ t('仅本浏览器保存，不改变节点身份或绑定飞控。') }}</small></div><dl class="detail-list"><div><dt>{{ t('观测状态') }}</dt><dd>{{ stateLabel(nodeState(node, network.snapshot, network.now, network.interrupted)) }}</dd></div><div><dt>{{ t('报告年龄') }}</dt><dd class="num">{{ ageText(node.reportedAt === null ? null : network.now - node.reportedAt) }}</dd></div><div><dt>{{ t('电量') }}</dt><dd class="num">{{ node.batteryPercent ?? '—' }}{{ node.batteryPercent === null ? '' : '%' }}</dd></div><div><dt>{{ t('关联设备') }}</dt><dd class="binding">{{ node.binding?.id ?? t('未绑定') }}</dd></div><div><dt>RSSI / SNR</dt><dd class="num">{{ node.radio.rssiDbm ?? '—' }} / {{ node.radio.snrDb ?? '—' }}</dd></div><div><dt>{{ t('接收信道') }}</dt><dd class="num">{{ node.radio.channel ?? '—' }}</dd></div><div><dt>{{ t('频率') }}</dt><dd class="num">{{ node.radio.frequencyHz ? (node.radio.frequencyHz / 1e6).toFixed(3) + ' MHz' : '—' }}</dd></div></dl><div class="position-block"><span class="detail-overline">{{ t('位置来源') }}</span><template v-if="node.position"><strong class="num">{{ node.position.lat.toFixed(6) }}, {{ node.position.lon.toFixed(6) }}</strong><small>{{ node.position.source }} · {{ hasPosition(node, network.now, network.snapshot.reportTimeoutMs) ? t('有效定位') : t('定位过期') }}</small></template><span v-else>{{ t('未提供 GPS，不补造位置。') }}</span></div><div class="related-links"><span class="detail-overline">{{ t('相关方向') }} / {{ nodeLinks.length }}</span><button v-for="e in nodeLinks.slice(0, 6)" :key="e.id" @click="chooseLink(e.id)"><span>{{ labelOf(e.from) }} → {{ labelOf(e.to) }}</span><small>{{ e.kind.toUpperCase() }}</small></button></div></template>
        <p v-else class="list-empty">{{ t('选择节点或方向，查看原始观测依据。') }}</p>
      </aside>
    </div>

    <NetworkRelations v-if="network.snapshot" :snapshot="network.snapshot" :selected="selected" :selected-link="selectedLink" :now="network.now" :interrupted="network.interrupted" :link-filter="linkFilter" :frame="topologyFrame" @link="chooseLink" />
    <NetworkEngineering v-if="workspace === 'real' && network.configuration.mode === 'gateway'" :key="network.connectionKey" />

    <section class="network-history">
      <div class="history-heading"><div><span class="kicker">OBSERVATION TIMELINE</span><h2>{{ t('观测记录与回放') }}</h2></div><div class="history-actions"><select v-model="linkFilter" :aria-label="t('连线类型')"><option value="all">{{ t('全部连线') }}</option><option value="wifi">Wi-Fi / ESP-NOW</option><option value="lora">LoRa</option></select><button :disabled="!network.capabilities?.recording || network.mode !== 'live' || network.busy || (network.observationLayer !== 'lora' && !network.recording)" :class="{ recording: network.recording }" @click="network.toggleRecording"><i />{{ network.recording ? t('结束记录') : t('开始记录') }}</button><select v-model="replayId" :aria-label="t('选择网络记录')" @focus="network.loadSessions"><option value="">{{ t('选择网络记录') }}</option><option v-for="session in network.sessions" :key="session.id" :value="session.id">{{ session.label }} · {{ session.frames }} {{ t('帧') }}</option></select><button :disabled="!replayId || network.busy || !!network.recording" @click="network.openReplay(replayId)">{{ t('载入回放') }}</button></div></div>
      <p v-if="network.capabilities?.engineering" class="recording-note">{{ t('SQLite 持久记录仅保存 LoRa 拓扑，不含 IP/Agent 原包时间线。关闭浏览器不会结束录制；每页最多 25 帧，保留原采集时间，不给历史套用当前清单。') }}</p>
      <p v-if="network.capabilities?.mock" class="recording-note">{{ t('临时记录仅存内存，重启清空；每次最多 600 帧，结束记录后可载入回放。') }}</p>
      <div v-if="network.mode === 'replay' && network.replay" class="replay-controls" data-test="network-replay"><button class="play-button" :aria-label="network.playing ? t('暂停回放') : t('播放回放')" @click="network.play">{{ network.playing ? 'Ⅱ' : '▶' }}</button><input type="range" min="0" :max="network.replayTotal - 1" :disabled="network.busy" :value="network.frame" :aria-label="t('回放进度')" @input="network.seek(Number(($event.target as HTMLInputElement).value))"><span class="num">{{ network.frame + 1 }} / {{ network.replayTotal }}</span><select :value="network.speed" :aria-label="t('回放倍速')" @change="network.setSpeed(Number(($event.target as HTMLSelectElement).value))"><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select><span class="replay-badge">{{ t('历史快照，不发送任何无线数据') }}</span></div>
      <div class="event-strip"><div v-for="event in [...(network.snapshot?.events ?? [])].reverse().slice(0, 6)" :key="event.id" class="event-item"><time class="num">{{ timeText(event.at) }}</time><span class="event-marker" :class="event.kind" /><div><strong>{{ eventLabel(event.code) }}</strong><small>{{ event.nodeId ? labelOf(event.nodeId) : network.snapshot?.receiver.label }}</small></div></div><span v-if="!network.snapshot?.events.length" class="no-events">{{ t('尚无观测事件') }}</span></div>
    </section>
    <footer class="workspace-footer"><span><i />{{ t('仅观测 · 不计算或下发通信路由 · 不影响飞行控制') }}</span><span class="num">{{ network.snapshot?.schema ?? 'network.snapshot.v1' }} / {{ network.snapshot?.sourceId ?? '—' }}</span></footer>
  </div>
